const ALL_B1_SEEDS: SeedTuple[] = [
  ...RAW_B1_SEEDS,
  ...ANALYTICAL_B1_SEEDS,
  ...FINAL_EXERCISE_B1_SEEDS,
];

const shuffleItems = <T,>(items: T[]): T[] => {
  const shuffled = [...items];

  for (let index = shuffled.length - 1; index > 0; index -= 1) {
    const randomIndex = Math.floor(Math.random() * (index + 1));
    [shuffled[index], shuffled[randomIndex]] = [shuffled[randomIndex], shuffled[index]];
  }

  return shuffled;
};

const TEACHING_PARTS: TeachingPart[] = [
  'globalContextSep',
  'psychology',
  'curriculum',
  'coreCurriculum',
  'learnerCentered',
  'classroomDevelopment',
  'digitalLearning',
  'assessment',
  'research',
  'qualityAssurance',
];

export const PART_B1_TEACHING_QUESTIONS: TeachingQuestion[] = ALL_B1_SEEDS.map(
  ([part, subject, question, answer, wrongA, wrongB, wrongC, explanation], index) => ({
    id: 4001 + index,
    part,
    subject,
    question,
    options: [answer, wrongA, wrongB, wrongC],
    correctAnswer: 0,
    explanation,
  }),
);

const shuffleQuestionOptions = (question: TeachingQuestion): Question => {
  const optionPairs = question.options.map((option, optionIndex) => ({
    option,
    isCorrect: optionIndex === question.correctAnswer,
  }));
  const shuffledPairs = shuffleItems(optionPairs);

  return {
    ...question,
    options: shuffledPairs.map((pair) => pair.option),
    correctAnswer: shuffledPairs.findIndex((pair) => pair.isCorrect),
  };
};

export const getPartB1TeachingExamQuestions = (
  count = PART_B1_TEACHING_EXAM_META.questionCount,
): Question[] => {
  if (count === PART_B1_TEACHING_EXAM_META.questionCount) {
    const questionsPerPart = Math.floor(count / TEACHING_PARTS.length);
    const balancedQuestions = TEACHING_PARTS.flatMap((part) =>
      shuffleItems(PART_B1_TEACHING_QUESTIONS.filter((question) => question.part === part)).slice(
        0,
        questionsPerPart,
      ),
    );

    return shuffleItems(balancedQuestions).map(shuffleQuestionOptions);
  }

  const safeCount = Math.min(count, PART_B1_TEACHING_QUESTIONS.length);
  return shuffleItems(PART_B1_TEACHING_QUESTIONS)
    .slice(0, safeCount)
    .map(shuffleQuestionOptions);
};
